ValidationRule.errorConditionFormula:
OR(
    AND(
        ISPICKVAL(Product_State__r.Payment_Type__c, "Percentage"),
        OR(
            ISBLANK(Percentage__c),
            NOT(ISBLANK(Fixed_Rate__c))
        )
    ),
    AND(
        ISPICKVAL(Product_State__r.Payment_Type__c, "Fixed Rate"),
        OR(
            ISBLANK(Fixed_Rate__c),
            NOT(ISBLANK(Percentage__c))
        )
    )
)
